def f(x):
    """Full-precision float for JSON; None for nan; the strings Infinity/-Infinity for infinities."""
    x = float(x)
    if math.isnan(x):
        return None
    if math.isinf(x):
        return "Infinity" if x > 0 else "-Infinity"
    return x


