# ---------------------------------------------------------------- chi-square for trend (formula of R prop.trend.test)
tx, tn, ts = np.array([15, 10, 8, 4.0]), np.array([20, 20, 20, 20.0]), np.array([1, 2, 3, 4.0])
pbar = tx.sum() / tn.sum()
sbar = (tn * ts).sum() / tn.sum()
num = ((tn * (ts - sbar)) * (tx / tn - pbar)).sum() ** 2
den = pbar * (1 - pbar) * (tn * (ts - sbar) ** 2).sum()
OUT["trend"] = {"x": tx.tolist(), "n": tn.tolist(), "score": ts.tolist(), "R": "prop.trend.test(x, n)",
                "X2": f(num / den), "p": f(stats.chi2.sf(num / den, 1)), "formula": "weighted regression SS of x/n on score"}

# ---------------------------------------------------------------- 2x2 measures (formula) on two tables
def measures(a, b, c, d):
    n1, n0 = a + b, c + d
    r1, r0 = a / n1, c / n0
    rr = r1 / r0
    se_lrr = math.sqrt(1 / a - 1 / n1 + 1 / c - 1 / n0)
    orr = a * d / (b * c)
    se_lor = math.sqrt(1 / a + 1 / b + 1 / c + 1 / d)
    rd = r1 - r0
    se_rd = math.sqrt(r1 * (1 - r1) / n1 + r0 * (1 - r0) / n0)
    # Newcombe (1998) method 10: difference of Wilson intervals
    def wil(x, n):
        ci = stats.binomtest(x, n).proportion_ci(0.95, method="wilson")
        return ci.low, ci.high
    l1, u1 = wil(a, n1)
    l0, u0 = wil(c, n0)
    nlo = rd - math.sqrt((r1 - l1) ** 2 + (u0 - r0) ** 2)
    nhi = rd + math.sqrt((u1 - r1) ** 2 + (r0 - l0) ** 2)
    rt = (a + c) / (n1 + n0)
    return {"table": [[a, b], [c, d]],
            "risk1": f(r1), "risk0": f(r0),
            "RR": f(rr), "RR.waldLog": [f(rr * math.exp(-Z975 * se_lrr)), f(rr * math.exp(Z975 * se_lrr))],
            "OR": f(orr), "OR.woolf": [f(orr * math.exp(-Z975 * se_lor)), f(orr * math.exp(Z975 * se_lor))],
            "RD": f(rd), "RD.wald": [f(rd - Z975 * se_rd), f(rd + Z975 * se_rd)], "RD.newcombe10": [f(nlo), f(nhi)],
            "AFe": f((rr - 1) / rr), "AFp": f((rt - r0) / rt), "AFeFromOR": f((orr - 1) / orr)}


OUT["twoByTwo.serosurvey"] = {**measures(116, 364, 27, 209), "source": "numbers.json assoc.table (crudePR, crudePOR)"}
OUT["twoByTwo.small"] = {**measures(12, 8, 5, 15), "source": "defined here"}

# ---------------------------------------------------------------- Mantel-Haenszel on three strata defined here, Breslow-Day and Tarone (formula)
STRATA = [[[10, 20], [5, 25]], [[8, 12], [6, 24]], [[15, 5], [9, 11]]]
R_ = S_ = PR_ = PSQR = QS_ = 0.0
sa = sea = va = 0.0
for (a, b), (c, d) in STRATA:
    T_ = a + b + c + d
    r_, s_ = a * d / T_, b * c / T_
    P_, Q_ = (a + d) / T_, (b + c) / T_
    R_ += r_; S_ += s_; PR_ += P_ * r_; PSQR += P_ * s_ + Q_ * r_; QS_ += Q_ * s_
    m1, n1_, n0_ = a + c, a + b, c + d
    sa += a; sea += n1_ * m1 / T_
    va += n1_ * n0_ * m1 * (b + d) / (T_ ** 2 * (T_ - 1))
ormh = R_ / S_
vlog = PR_ / (2 * R_ ** 2) + PSQR / (2 * R_ * S_) + QS_ / (2 * S_ ** 2)


def expected_a(tab, psi):
    (a, b), (c, d) = tab
    n1_, n0_, m1 = a + b, c + d, a + c
    # solve e(n0 - m1 + e) = psi (n1 - e)(m1 - e) for e in the admissible range
    qa = 1 - psi
    qb = (n0_ - m1) + psi * (n1_ + m1)
    qc = -psi * n1_ * m1
    lo, hi = max(0, m1 - n0_), min(n1_, m1)
    roots = np.roots([qa, qb, qc]) if abs(qa) > 1e-15 else np.array([-qc / qb])
    root = [float(r.real) for r in np.atleast_1d(roots) if abs(r.imag) < 1e-12 and lo - 1e-9 <= r.real <= hi + 1e-9]
    return root[0]


bd = 0.0
sum_diff = sum_var = 0.0
for tab in STRATA:
    (a, b), (c, d) = tab
    e = expected_a(tab, ormh)
    n1_, n0_, m1 = a + b, c + d, a + c
    var = 1 / (1 / e + 1 / (n1_ - e) + 1 / (m1 - e) + 1 / (n0_ - m1 + e))
    bd += (a - e) ** 2 / var
    sum_diff += a - e
    sum_var += var
tarone = bd - sum_diff ** 2 / sum_var
cmh = (abs(sa - sea) - 0.5) ** 2 / va
OUT["mantelHaenszel.threeStrata"] = {
    "strata": STRATA, "R": "mantelhaen.test(array(...)); DescTools::BreslowDayTest(x, correct = TRUE)",
    "ORmh": f(ormh), "ciRGB": [f(ormh * math.exp(-Z975 * math.sqrt(vlog))), f(ormh * math.exp(Z975 * math.sqrt(vlog)))],
    "CMHcorrected": f(cmh), "pCMH": f(stats.chi2.sf(cmh, 1)),
    "breslowDay": f(bd), "pBreslowDay": f(stats.chi2.sf(bd, len(STRATA) - 1)),
    "tarone": f(tarone), "pTarone": f(stats.chi2.sf(tarone, len(STRATA) - 1))}

# ---------------------------------------------------------------- diagnostic accuracy (course 107013/107015 and 107014)
def dx(tp, fn, fp, tn):
    se, sp = tp / (tp + fn), tn / (tn + fp)
    lrp, lrn = se / (1 - sp), (1 - se) / sp
    sep = math.sqrt(1 / tp - 1 / (tp + fn) + 1 / fp - 1 / (fp + tn))
    sen = math.sqrt(1 / fn - 1 / (tp + fn) + 1 / tn - 1 / (fp + tn))
    out = {"TP": tp, "FN": fn, "FP": fp, "TN": tn,
           "Se": f(se), "Sp": f(sp), "PPV": f(tp / (tp + fp)), "NPV": f(tn / (tn + fn)),
           "accuracy": f((tp + tn) / (tp + fn + fp + tn)),
           "LRpos": f(lrp), "LRpos.log": [f(lrp * math.exp(-Z975 * sep)), f(lrp * math.exp(Z975 * sep))],
           "LRneg": f(lrn), "LRneg.log": [f(lrn * math.exp(-Z975 * sen)), f(lrn * math.exp(Z975 * sen))]}
    for k, (xx, nn) in {"Se": (tp, tp + fn), "Sp": (tn, tn + fp), "PPV": (tp, tp + fp), "NPV": (tn, tn + fn)}.items():
        bt = stats.binomtest(xx, nn)
        wi, ex = bt.proportion_ci(0.95, "wilson"), bt.proportion_ci(0.95, "exact")
        out[k + ".wilson"] = [f(wi.low), f(wi.high)]
        out[k + ".exact"] = [f(ex.low), f(ex.high)]
    return out


OUT["dx.course107013"] = {**dx(90, 10, 60, 120), "source": "course items 107013 and 107015 (same table)", "R": "epiR::epi.tests(as.table(matrix(c(90, 10, 60, 120), 2)))"}
OUT["dx.course107014"] = {**dx(32, 8, 16, 944), "source": "course item 107014 (FeLV)"}

# ---------------------------------------------------------------- kappa (formula)
K = np.array([[20, 5, 1], [4, 15, 6], [1, 3, 25]], dtype=float)
n = K.sum()
po = np.trace(K) / n
pe = (K.sum(1) * K.sum(0)).sum() / n ** 2
k_ = K.shape[0]
res = {"table": K.astype(int).tolist(), "R": "irr::kappa2(ratings, weight = 'unweighted' / 'equal' / 'squared')",
       "po": f(po), "kappa": f((po - pe) / (1 - pe))}
for name, wfun in [("linear", lambda i, j: 1 - abs(i - j) / (k_ - 1)), ("quadratic", lambda i, j: 1 - ((i - j) / (k_ - 1)) ** 2)]:
    W = np.array([[wfun(i, j) for j in range(k_)] for i in range(k_)])
    pow_ = (W * K).sum() / n
    pew = (W * np.outer(K.sum(1), K.sum(0))).sum() / n ** 2
    res[f"kappa.{name}"] = f((pow_ - pew) / (1 - pew))
OUT["kappa.threeLevel"] = res
K2 = np.array([[40, 9], [6, 45]], dtype=float)
n2 = K2.sum()
po2 = np.trace(K2) / n2
pe2 = (K2.sum(1) * K2.sum(0)).sum() / n2 ** 2
OUT["kappa.twoByTwo"] = {"table": K2.astype(int).tolist(), "R": "epiR::epi.kappa(m)", "po": f(po2), "kappa": f((po2 - pe2) / (1 - pe2)),
                         "PABAK": f(2 * po2 - 1), "prevalenceIndex": f(abs(K2[0, 0] - K2[1, 1]) / n2), "biasIndex": f(abs(K2[0, 1] - K2[1, 0]) / n2)}
OUT["agreement.course107027"] = {"source": "course item 107027", "agree": 865, "n": 986, "po": f(865 / 986)}

# ---------------------------------------------------------------- ICC (one-way ANOVA estimator, unequal clusters) for a continuous outcome
CL = {"F1": [4.1, 3.8, 4.5, 4.0], "F2": [5.2, 5.0, 4.8], "F3": [3.1, 3.5, 3.3, 2.9, 3.6], "F4": [4.4, 4.9]}
vals = np.concatenate([np.array(v) for v in CL.values()])
sizes = np.array([len(v) for v in CL.values()])
Ntot, kc = len(vals), len(CL)
gm = vals.mean()
msb = sum(len(v) * (np.mean(v) - gm) ** 2 for v in CL.values()) / (kc - 1)
msw = sum(((np.array(v) - np.mean(v)) ** 2).sum() for v in CL.values()) / (Ntot - kc)
n0 = (Ntot - (sizes ** 2).sum() / Ntot) / (kc - 1)
icc = (msb - msw) / (msb + (n0 - 1) * msw)
OUT["icc.continuous"] = {"clusters": CL, "R": "ICC::ICCest(cluster, y) (one-way ANOVA estimator); formula in base R",
                         "MSB": f(msb), "MSW": f(msw), "n0": f(n0), "ICC": f(icc),
                         "DEFFmeanSize": f(1 + (Ntot / kc - 1) * icc)}

# ---------------------------------------------------------------- multiplicity
pv = [0.01, 0.04, 0.03, 0.005]
order = np.argsort(pv)
m = len(pv)
holm = np.empty(m)
running = 0.0
for rank, idx in enumerate(order):
    running = max(running, min(1.0, (m - rank) * pv[idx]))
    holm[idx] = running
OUT["padjust"] = {"p": pv, "R": "p.adjust(p, 'holm'); p.adjust(p, 'bonferroni')",
                  "holm": [f(v) for v in holm], "bonferroni": [f(min(1.0, m * v)) for v in pv]}

# ---------------------------------------------------------------- true prevalence (Rogan-Gladen), closed form
OUT["truePrevalence.closedForm"] = {"AP": 0.2, "Se": 0.95, "Sp": 0.98, "TP": f((0.2 + 0.98 - 1) / (0.95 + 0.98 - 1))}

# ---------------------------------------------------------------- sample size, closed forms (course mode and the alternatives)
za, zb = stats.norm.ppf(0.975), stats.norm.ppf(0.8)
p0_, OR_ = 0.25, 3.0
p1_ = p0_ * OR_ / (1 + p0_ * (OR_ - 1))
pb = (p1_ + p0_) / 2
